def match(pattern: str, text: str) -> bool:
    """
    Implements a recursive backtracking algorithm for regex matching
    supporting literal characters, '.' (any character), '*' (zero or more 
    of the preceding element), and '+' (one or more of the preceding element).
    """

    def is_match(p_idx: int, t_idx: int) -> bool:
        if p_idx == len(pattern) and t_idx == len(text):
            return True
        if p_idx < len(pattern) and t_idx == len(text):
            return all(c == '*' or c in ('+', '.') for c in pattern[p_idx:])
        if p_idx == len(pattern):
            return False

        p_char = pattern[p_idx]

        if p_char == '*':
            if p_idx == 0:  # '*' cannot be the first character
                return False
            prev_char = pattern[p_idx - 1]
            return (t_idx < len(text) and (text[t_idx] == prev_char or prev_char == '.')
                    and is_match(p_idx, t_idx + 1)) or is_match(p_idx + 1, t_idx)

        if p_char == '+':
            if t_idx >= len(text):
                return False
            prev_char = pattern[p_idx - 1]
            return ((text[t_idx] == prev_char or prev_char == '.') and is_match(p_idx, t_idx + 1)) or is_match(p_idx + 1, t_idx)

        if t_idx < len(text) and (p_char == text[t_idx] or p_char == '.'):
            return is_match(p_idx + 1, t_idx + 1)

        return False

    return is_match(0, 0)
